  $userId=(int)$pdo->query('SELECT id FROM tbl_user ORDER BY id LIMIT 1')->fetchColumn(); $warehouseId=(int)$pdo->query('SELECT id FROM tbl_warehouse WHERE active_status=1 ORDER BY id LIMIT 1')->fetchColumn();
  if(!$userId||!$warehouseId) throw new RuntimeException('Faltan datos base.'); $suffix=substr(uniqid(),-8); $ruc='20'.str_pad((string)random_int(1,999999999),9,'0',STR_PAD_LEFT); $today=date('Y-m-d');
